function scoreDock(){return `<div class="score-dock ${selected.size?'has-selection':''}"><div><strong>${selected.size?`已选 ${selected.size} 位同学`:'选中学生后，在这里批量加减分'}</strong><small>${selected.size?'每次操作都可在积分记录中撤销':petEnabled()?'支持多选 · 普通积分独立操作':'支持多选 · 积分和宠物成长同步'}</small></div><div class="score-inputs"><select id="score-reason" aria-label="积分原因"><option>课堂表现</option>${ScoreRules.list(state).map(r=>`<option>${esc(r.label)}</option>`).join('')}</select><input id="score-delta" aria-label="分值，可正可负" type="number" min="-100" max="100" step="1" value="1"><button class="button" data-do="batch-apply" ${!selected.size?'disabled':''}>确认加/减分</button><button class="button" data-do="batch-minus" ${!selected.size?'disabled':''}>− 减分</button><button class="button primary" data-do="batch-plus" ${!selected.size?'disabled':''}>＋ 加分</button><button class="button" data-do="flexible-minus" ${!selected.size?'disabled':''}>灵活扣分</button><button class="button" data-do="flexible-plus" ${!selected.size?'disabled':''}>灵活加分</button></div></div>`;}
