function petEgg(){return `<svg class="pet-egg" viewBox="0 0 240 240" aria-hidden="true"><ellipse cx="120" cy="197" rx="63" ry="13" fill="#e5dbed"/><path d="M120 40C84 40 56 120 62 156C69 207 172 206 178 156C184 120 156 40 120 40Z" fill="#fff7df" stroke="#c9b997" stroke-width="4"/><circle cx="91" cy="137" r="13" fill="#d2c5ee"/><circle cx="141" cy="100" r="11" fill="#b9ddca"/><circle cx="142" cy="168" r="15" fill="#f3c4c5"/><path d="M93 72L108 84L121 70L134 85L146 75" fill="none" stroke="#c9b997" stroke-width="3"/></svg>`;}
function unadoptedPetCard(s,compact=false){const p=growth(s);return `<article class="pet-student-card unadopted-card" data-pet-student="${s.id}"><div class="pet-card-top"><span class="level-badge">等待破壳</span><span class="stage-counter">荣誉徽章 ${p.medalTotal}</span></div><div class="pet-scene">${petEgg()}</div><div class="pet-owner"><h3>${esc(s.name)}</h3><span>${esc(s.group)}</span></div><p class="pet-partner">伙伴：未领养</p><p class="pet-fine-print">${p.graduates.length?'荣誉永久保留，迎接下一位伙伴':'选一位喜欢的成长伙伴'}</p><div class="pet-card-actions"><button class="button primary" data-do="adopt-pet" data-id="${s.id}">领养宠物</button><button class="button" data-do="pet-honors" data-id="${s.id}">毕业相册</button></div></article>`;}
function petCard(s,compact=false){
 const p=growth(s);if(!p.adopted)return unadoptedPetCard(s,compact);
 const stage=p.shape,focused=state.settings.petFocusId===s.id;
 return `<article class="pet-student-card ${selected.has(s.id)?'selected':''} ${focused?'is-featured':''} ${p.maxed?'is-maxed':''}" data-pet-student="${s.id}">
 <div class="pet-card-top"><span class="level-badge">LV.${p.level}${p.maxed?' · MAX':''}</span><span class="stage-counter">形态 ${stage}/7 · 徽章 ${p.medalTotal}</span>${compact?'':`<button class="pet-select ${selected.has(s.id)?'checked':''}" data-student="${s.id}" aria-label="选择${esc(s.name)}" aria-pressed="${selected.has(s.id)}">${selected.has(s.id)?'✓':'＋'}</button>`}</div>
 <button class="pet-scene pet-${p.pet}" data-do="${compact?'pet-reward':'pet-detail'}" data-id="${s.id}" aria-label="${compact?'鼓励':'查看'}${esc(s.name)}的宠物">${petSvg(p.pet,true,p.level)}<span class="scene-sparkle">✦</span></button>
 <div class="pet-owner"><h3 title="${esc(s.name)}">${esc(s.name)}</h3><span title="${esc(s.group)}">${esc(s.group)}</span></div><p class="pet-partner">伙伴：${esc(petNames[p.pet])} · ${esc(PetArt.stages[stage-1])}</p>
 <div class="pet-growth"><span>${p.maxed?'成长完成':'成长值'} <strong>${growthText(p)}</strong></span><span>积分 ${s.score}</span></div><div class="progress"><i style="width:${growthPercent(p)}%"></i></div>
 <div class="pet-card-actions"><button class="button primary" data-do="${p.enabled&&p.maxed?'pet-graduate':'pet-reward'}" data-id="${s.id}">${p.enabled&&p.maxed?'✦ 安排毕业':'✦ 鼓励成长'}</button><button class="button" data-do="pet-album" data-id="${s.id}">进化图鉴</button></div></article>`;
}
function petNavigation(standalone=false){return `<div class="pet-care-navigation"><div class="segmented"><button data-do="pet-tab" data-tab="students" class="${petTab==='students'?'active':''}">学生伙伴</button><button data-do="pet-tab" data-tab="groups" class="${petTab==='groups'?'active':''}">按小组看</button><button data-do="pet-tab" data-tab="rankings" class="${petTab==='rankings'?'active':''}">宠物排行榜</button><button data-do="pet-tab" data-tab="records" class="${petTab==='records'?'active':''}">成长记录</button></div><div class="button-row pet-extra-entry">${PetExtraUI.entry()}${standalone?'<button class="button" data-do="open-panel">积分面板</button>':''}</div></div>`;}
function petsView(standalone=false){
 if(petDetailId){const s=state.students.find(s=>s.id===petDetailId);if(s)return petDetailView(s);}
 const list=filtered(),groups=GroupTools.names(state).filter(g=>list.some(s=>s.group===g)),enabled=petEnabled();
 const body=petTab==='rankings'?petRankingsView():petTab==='records'?petRecordsView():`<div class="section-toolbar"><div class="filters"><input id="search" type="search" placeholder="搜索学生姓名" aria-label="搜索学生姓名" value="${esc(filter)}"><select id="group-filter" aria-label="筛选小组"><option value="">全部小组</option>${GroupTools.names(state).map(g=>`<option ${g===groupFilter?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div class="button-row"><button class="button" data-do="select-all">${list.length&&list.every(s=>selected.has(s.id))?'取消全选':'批量选择'}</button><span class="muted">${list.length} 位伙伴</span></div></div>${petTab==='groups'?'<p class="pet-group-note">每位组员有自己的宠物，小组鼓励会逐人增加成长</p>':''}
 ${list.length?(petTab==='groups'?groups.map(g=>`<section class="pet-group"><div class="section-label"><h3>${esc(g)} <small>${list.filter(s=>s.group===g).length} 位同学</small></h3><button class="button" data-do="pet-group-reward" data-group="${esc(g)}">鼓励本组已领养伙伴</button></div><div class="pet-grid">${list.filter(s=>s.group===g).map(s=>petCard(s)).join('')}</div></section>`).join(''):`<div class="pet-grid">${list.map(s=>petCard(s)).join('')}</div>`):'<div class="empty">还没有匹配的伙伴<br>在「学生积分」添加同学，或在「班级设置」导入名单</div>'}
 <div class="pet-batch-bar ${selected.size?'has-selection':''}"><div><strong>${selected.size?`已选 ${selected.size} 位伙伴`:'每一次鼓励，都让伙伴向前一步'}</strong><small>点击卡片的 ＋ 进行多选，批量操作可整笔撤销</small></div><button class="button primary" data-do="pet-reward" ${selected.size?'':'disabled'}>✦ 批量鼓励成长</button></div>`;
 return `<section class="pet-garden-intro"><div><span class="eyebrow">成长概览</span><h2>${state.students.filter(s=>growth(s).adopted).length} 位伙伴，和同学一起成长</h2><div class="pet-rule-summary">${enabled?`六段成长门槛 ${state.settings.petRules.thresholds.join(' / ')}`:`保留原成长规则 · 每 ${state.settings.petStep} 点升1级`} <button class="text-button" data-do="pet-rules">成长规则</button></div></div><div class="pet-garden-actions"><button class="button" data-do="pet-catalog">${Object.keys(petNames).length} 种伙伴图鉴</button><small>每种 7 个阶段 · 自由选择喜欢的伙伴</small></div></section>
 ${enabled?'':`<div class="pet-legacy-banner"><div><strong>当前保留旧版成长规则</strong><span>启用后可单独加减成长、安排毕业；原积分和累计成长保留</span></div><button class="button" data-do="pet-enable">启用分段成长与毕业</button></div>`}
 ${petNavigation(standalone)}${body}`;
}
function petDetailView(s){
 const p=growth(s),stage=p.shape;
 const heading=`<div class="pet-detail-heading"><button class="text-button" data-do="pet-back">‹ 返回宠物花园</button><div class="button-row"><button class="button" data-do="edit-student" data-id="${s.id}">学生档案</button><button class="button" data-do="pet-honors" data-id="${s.id}">🏅 毕业相册</button><button class="button" data-do="pet-focus" data-id="${s.id}">◧ 放到悬浮侧栏</button></div></div>`;
 if(!p.adopted)return `${heading}<div class="pet-unadopted-detail">${unadoptedPetCard(s)}<div><h2>下一段成长，从新的相遇开始</h2><p>${esc(s.name)}已拥有 ${p.medalTotal} 枚永久荣誉徽章</p><p>毕业伙伴留在相册，重新领养后从 LV.1 开始</p><button class="button" data-do="pet-honors" data-id="${s.id}">查看毕业荣誉世界</button></div></div>${petRecordsView(s.id,true)}`;
 return `${heading}<section class="pet-detail-hero"><div class="pet-big-stage pet-${p.pet}"><span class="stage-constellation">✧ · ✦ · ✧</span>${petSvg(p.pet,true,p.level)}<span class="stage-platform"></span><span class="pill">${esc(PetArt.stages[stage-1])}</span></div><div class="pet-profile"><span class="eyebrow">${esc(s.group)} · 专属成长伙伴</span><h2>${esc(s.name)}的${esc(petNames[p.pet])}</h2><span class="level-badge">LV.${p.level}${p.maxed?' · MAX':''}</span><p class="pet-detail-copy">${p.maxed?'七段成长已完成，为伙伴安排一次闪亮的毕业吧':'今天的小小努力，正在让伙伴变得更闪亮'}</p><div class="pet-growth"><strong>${p.maxed?'已满级':`本级成长 ${p.current} / ${p.needed}`}</strong><span>${p.maxed?'毕业可获得 1 枚永久荣誉徽章':`还差 ${p.needed-p.current} 点升级`}</span></div><div class="progress"><i style="width:${growthPercent(p)}%"></i></div><div class="pet-totals"><div><strong>${s.score}</strong><small>普通积分</small></div><div><strong>${p.growth}</strong><small>${p.enabled?'本轮成长':'累计成长'}</small></div><div><strong>${p.medalTotal}</strong><small>永久荣誉徽章</small></div></div><div class="button-row">${p.enabled&&p.maxed?`<button class="button primary large-button" data-do="pet-graduate" data-id="${s.id}">✦ 安排毕业</button>`:''}<button class="button ${p.maxed?'':'primary'} large-button" data-do="pet-reward" data-id="${s.id}">✦ ${p.enabled?'调整成长':'送上鼓励'}</button><button class="button" data-do="pet-album" data-id="${s.id}">进化图鉴</button></div><p class="pet-fine-print">${p.enabled?'宠物成长独立记账，不修改普通积分。毕业保留本轮成长快照、物种与永久徽章；再领养开启新一轮。':'旧版：加分增加成长；扣分不减成长。撤销加分会回退相应成长和等级。Lv.7之后继续记录成长，保留第7种形态。'}${p.overflow?` 当前包含 ${p.overflow} 点满级后成长，毕业快照完整保留。`:''}</p>${p.enabled?'':`<button class="text-button" data-do="pet-enable">启用分段成长与毕业 →</button>`}</div></section>
 <section class="evolution-section"><div class="section-label"><h3>七段成长，每一级都不一样</h3><small>${state.settings.hideLateForms?'老师已隐藏最后两级预览':'横向滑动浏览 · 点击查看大图'}</small></div><div class="evolution-track">${Array.from({length:7},(_,i)=>`<button class="evolution-tile ${stage===i+1?'current':''}" data-do="pet-album" data-id="${s.id}" data-level="${i+1}"><span>LV.${i+1}</span>${petPreviewArt(p.pet,i+1)}<strong>${hiddenPetForm(i+1)?'神秘形态':esc(PetArt.stages[i])}</strong><small>${hiddenPetForm(i+1)?'老师已隐藏':stage===i+1?'当前形态':stage>i+1?'已到达':'可预览'}</small></button>`).join('')}</div></section>${petRecordsView(s.id,true)}`;
}
function petFloatingView(){
 const focus=state.students.find(s=>s.id===state.settings.petFocusId),list=focus?[focus,...state.students.filter(s=>s.id!==focus.id)]:state.students;
 return `<div class="pet-floating"><div class="utility-title"><span>♧ 悬浮宠物 · 拖动此处</span><button class="icon-button" data-do="close-window" aria-label="关闭宠物侧栏">×</button></div><div class="floating-pet-toolbar"><button class="text-button" data-do="open-main">⌂ 主界面</button><button class="text-button" data-do="open-panel">学生积分</button><button class="text-button" data-do="open-pets">课堂展示</button></div><div class="floating-pet-content"><p class="muted">${esc(state.settings.className)} · 点击伙伴送鼓励</p><label class="floating-student-label">优先展示<select id="pet-student-select" aria-label="优先展示学生"><option value="" disabled ${!focus?'selected':''}>选择一位同学</option>${state.students.map(s=>`<option value="${s.id}" ${focus?.id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><div class="floating-pet-list">${list.length?list.map(s=>petCard(s,true)).join(''):'<div class="empty">请先在主界面添加学生</div>'}</div></div></div>`;
}
function rewardDialog(){
 const requested=new Set(pendingRewardIds),students=state.students.filter(s=>requested.has(s.id)&&growth(s).adopted),skipped=requested.size-students.length;
 if(!students.length)return toast('请先为选中的同学领养宠物');pendingRewardIds=students.map(s=>s.id);
 const enabled=petEnabled();pendingRewardContext={panelId:PanelTools.currentId(state),enabled,reasons:petReasons(),expectedCycles:students.map(s=>({id:s.id,cycleId:growth(s).activeCycleId}))};
 modal(`<h2>${enabled?'送上鼓励，记录成长':'为努力送上鼓励'}</h2><p class="reward-students">${esc(students.map(s=>s.name).join('、'))}</p><p>${enabled?'只调整宠物成长，普通积分保持不变':'旧版规则：加分同步增加宠物成长；扣分不减成长'}</p>${students.length===1?`<button class="button pet-switch-entry" data-do="pet-switch" data-id="${students[0].id}">换宠物</button>`:''}${skipped?`<p class="rule-warning">本次跳过 ${skipped} 位尚未领养的同学</p>`:''}<div class="pet-reasons">${pendingRewardContext.reasons.map((r,i)=>`<button class="reason-card ${r.delta<0?'minus':''}" data-do="pet-reason" data-index="${i}"><span>${esc(r.label)}</span><strong>${r.delta>0?'+':''}${r.delta}<small> ${enabled?'成长':'分'}</small></strong><em>${enabled?'普通积分不变':r.delta>0?`成长 +${r.delta}`:'成长保持不变'}</em></button>`).join('')}</div>${enabled?`<form id="pet-growth-form" data-panel-id="${PanelTools.currentId(state)}"><h3>自定义成长</h3><div class="pet-custom-growth"><label>成长值<input name="delta" type="number" min="1" max="100" value="1" step="1" required></label><label>原因<input name="reason" maxlength="80" value="课堂表现" required></label></div><div class="button-row"><button class="button" type="submit" name="direction" value="minus">− 减少成长</button><button class="button primary" type="submit" name="direction" value="plus">＋ 增加成长</button></div></form>`:''}<p class="pet-fine-print">${students.length>1?'本次为批量操作，撤销时会同时还原所有选中学生。':'可在成长记录中撤销整笔。'}${enabled?'成长减少可能降级；下限按本班成长设置执行，撤销只还原实记差额。':''}</p>`);
 $('#modal .dialog').classList.add('reward-dialog');
}
function stageRuleFields(values){return `<div class="pet-threshold-grid">${values.map((v,i)=>`<label>LV.${i+1} → LV.${i+2}<input class="pet-threshold" name="threshold-${i}" type="number" min="1" max="1000000000" step="1" value="${v}" required><small>本段所需成长值</small></label>`).join('')}</div><div class="button-row pet-presets"><button type="button" class="button" data-do="pet-preset" data-preset="reference">虾米同款成长值 · 5 / 10 / 15 / 20 / 25 / 30</button><button type="button" class="button" data-do="pet-preset" data-preset="five">每段都是 5</button></div>`;}
function rulesDialog(enable=false){
 const enabled=petEnabled(),values=state.settings.petRules?.thresholds||[5,5,5,5,5,5];
 modal(`<h2>${enable?'启用分段成长与毕业':'宠物成长规则'}</h2><p>${enabled||enable?'七级成长分为六段，每段可单独调整；LV.7 满级后可安排毕业':'当前仍使用旧版统一门槛，既有积分与成长记账方式保留'}</p>${!enabled&&!enable?`<form id="pet-rules-form" data-mode="legacy" data-panel-id="${PanelTools.currentId(state)}"><label>旧版每级所需成长值<input id="pet-step" type="number" min="1" max="100" step="1" value="${state.settings.petStep}" required></label><div class="rule-warning">更改旧版门槛只重新计算显示等级和形态，不修改学生积分、累计成长、照片或历史记录</div><div class="dialog-actions"><button type="button" class="button" data-do="modal-close">取消</button><button type="submit" class="button primary">保存旧版规则</button></div></form><hr class="pet-rule-divider"><h3>六段成长与毕业</h3><p>启用后，宠物页可以单独调整成长，不修改普通积分；满级伙伴可以毕业并留存永久徽章与相册</p><button class="button primary" data-do="pet-enable">配置并启用分段成长与毕业</button>`:`<form id="pet-rules-form" data-mode="stages" data-panel-id="${PanelTools.currentId(state)}"><label>快速统一每段成长值<input id="pet-step" type="number" min="1" max="1000000000" step="1" value="${values.every(v=>v===values[0])?values[0]:''}" placeholder="输入后同步下面六格"></label>${stageRuleFields(values)}<div class="rule-warning">${enabled?'保存后重新计算当前等级和形态；普通积分、本轮成长及已毕业快照不变。':'启用会完整承接既有累计成长，不修改普通积分、照片或历史记录。已有旧版积分与成长的关联仍保留；宠物页后续操作独立记成长。请确认下面六段门槛。'}</div><div class="dialog-actions"><button type="button" class="button" data-do="modal-close">取消</button><button type="submit" class="button primary">${enabled?'保存六段规则':'启用分段成长与毕业'}</button></div></form>`}<label class="pet-visibility-setting"><input id="pet-hide-late" type="checkbox" ${state.settings.hideLateForms?'checked':''}>隐藏图鉴最后两级（LV.6 / LV.7，立即生效）</label><p class="pet-fine-print">只影响进化图鉴与全物种预览，不改变真实等级、伙伴卡片或毕业照片。默认可预览全部七级</p>`);
 $('#modal .dialog').classList.add('pet-rules-dialog');
}
function albumDialog(){
 const s=state.students.find(s=>s.id===petModalId);if(!s)return;const p=growth(s);
 modal(`<div class="album-title"><span class="eyebrow">EVOLUTION ALBUM · 原创伙伴</span><h2>${esc(petNames[p.pet])} · 进化图鉴</h2><p>左右滑动或滚动查看7种形态。${state.settings.hideLateForms?'老师已隐藏最后两级预览。':''}预览不会修改真实等级</p></div><div id="album-preview"></div><div class="album-track">${Array.from({length:7},(_,i)=>`<button class="album-tile" data-do="pet-preview" data-level="${i+1}" aria-label="预览第${i+1}级"><span>LV.${i+1}</span>${petPreviewArt(p.pet,i+1)}<strong>${hiddenPetForm(i+1)?'神秘形态':esc(PetArt.stages[i])}</strong></button>`).join('')}</div><p class="album-foot">${esc(s.name)} 当前 LV.${p.level} · ${p.maxed?'已满级':`本级成长 ${growthText(p)}`}</p>`);
 $('#modal .dialog').classList.add('album-dialog');renderAlbumPreview();
}
function renderAlbumPreview(){
 const s=state.students.find(s=>s.id===petModalId);if(!s||!$('#album-preview'))return;const p=growth(s);
 const n=Math.max(1,Math.min(7,petPreviewLevel)),actual=p.shape;
 $('#album-preview').innerHTML=`<button class="album-arrow" data-do="pet-preview" data-level="${Math.max(1,n-1)}" aria-label="上一形态" ${n===1?'disabled':''}>‹</button><div class="album-feature"><div class="album-art">${petPreviewArt(p.pet,n,true)}</div><span class="level-badge">LV.${n}</span><h3>${hiddenPetForm(n)?'神秘形态':esc(PetArt.stages[n-1])}</h3><p>${hiddenPetForm(n)?'老师已隐藏此形态':n===actual?'当前形态':n<actual?'已到达的形态':'未来的形态 · 预览'}</p></div><button class="album-arrow" data-do="pet-preview" data-level="${Math.min(7,n+1)}" aria-label="下一形态" ${n===7?'disabled':''}>›</button>`;
 document.querySelectorAll('.album-tile').forEach(b=>{const active=Number(b.dataset.level)===n;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
}
function showPetFeedback(students,direction='up'){
 if(!['main','pet','pets'].includes(role))return;
 const s=students[0],p=growth(s),down=direction==='down';
 $('#pet-feedback').innerHTML=`<section class="pet-celebration ${down?'pet-level-down':''}" role="status"><header class="celebration-header"><strong>成长时刻</strong><button type="button" class="icon-button celebration-close" data-do="pet-feedback-close" aria-label="关闭进化提示">×</button></header><div class="celebration-content"><span class="celebration-stars">${down?'↶':'✧ ✦ ✧'}</span><span class="pill">${down?'成长已调整':p.maxed?'成长满级':'成长升级'}</span><div class="celebration-art">${petSvg(p.pet,true,p.level)}</div><h2>${students.length===1?`${esc(s.name)}的伙伴${down?'等级回退了':'升级啦！'}`:`${students.length} 位伙伴${down?'等级已回退':'一起升级啦！'}`}</h2><p>${esc(petNames[p.pet])} · LV.${p.level} · ${esc(PetArt.stages[p.shape-1])}</p>${students.length>1?`<p class="celebration-names">${esc(students.slice(0,6).map(s=>s.name).join('、'))}${students.length>6?'等':''}</p>`:''}<button class="button primary" data-do="pet-feedback-close">${down?'知道了，继续努力':p.maxed?'伙伴已满级，准备毕业':'太棒了，继续成长！'}</button></div></section>`;
 clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>{$('#pet-feedback').innerHTML='';},7000);
}
function graduationDialog(id){const s=state.students.find(s=>s.id===id);if(!s)return;const p=growth(s);if(!p.enabled)return rulesDialog(true);if(!p.maxed||!p.adopted)return toast('伙伴达到 LV.7 后才能安排毕业');const panelId=PanelTools.currentId(state),expectedGraduation={pet:p.pet,growth:p.growth,thresholds:[...state.settings.petRules.thresholds],studentName:s.name,groupName:s.group};confirmDialog('为这位伙伴安排毕业？',`${s.name}的${petNames[p.pet]}已达到 LV.7。本轮 ${p.growth} 点成长会完整保存到毕业相册，并获得 1 枚永久荣誉徽章。毕业后回到未领养状态，再领养从 LV.1 开始；普通积分不变。`,()=>act({type:'pet.graduate',id,panelId,expectedCycleId:p.activeCycleId,expectedGraduation}));}
function showGraduationFeedback(s){if(!['main','pet','pets'].includes(role))return;const p=growth(s),g=p.graduates.at(-1);if(!g)return;$('#pet-feedback').innerHTML=`<section class="pet-celebration pet-graduation-feedback" role="status"><header class="celebration-header"><strong>毕业时刻</strong><button type="button" class="icon-button celebration-close" data-do="pet-feedback-close" aria-label="关闭毕业提示">×</button></header><div class="celebration-content"><span class="celebration-stars">✧ 🏅 ✧</span><span class="pill">毕业快乐</span><div class="celebration-art">${petSvg(g.petSnapshot,true,7)}</div><h2>+1 永久荣誉徽章</h2><p>${esc(s.name)}的${esc(petNames[g.petSnapshot])}已收入毕业荣誉世界</p><p>累计荣誉徽章 ${p.medalTotal} 枚 · 可以迎接下一位伙伴啦</p><button class="button primary" data-do="pet-feedback-adopt" data-id="${s.id}">领养新的伙伴</button></div></section>`;clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>{$('#pet-feedback').innerHTML='';},10000);}
function switchPetDialog(id){const student=state.students.find(s=>s.id===id);if(!student)return;const profile=growth(student);if(!profile.adopted)return adoptionDialog(id);modal(`<h2>${esc(student.name)}，换一位成长伙伴</h2><p>只更换当前伙伴外形，普通积分、成长、等级与已有荣誉保留</p><form id="pet-switch-form" data-id="${student.id}" data-panel-id="${PanelTools.currentId(state)}" data-expected-pet="${student.pet}" data-cycle-id="${profile.activeCycleId||''}">${petChoicePicker(student.pet)}<div class="dialog-actions"><button type="button" class="button" data-do="modal-close">取消</button><button type="submit" class="button primary">确定更换</button></div></form>`);$('#modal .dialog').classList.add('student-edit-dialog');}
function adoptionDialog(id){const s=state.students.find(s=>s.id===id);if(!s)return;if(!petEnabled()){editStudent(id);const checkbox=$('#student-form [name=adopted]');if(checkbox)checkbox.checked=true;return;}const p=growth(s);if(p.adopted)return toast('这位同学已经有成长伙伴');modal(`<h2>${esc(s.name)}，迎接新的成长伙伴</h2><p>${p.graduates.length&&!p.activeCycleId?'已有荣誉和毕业相册会永久保留，新伙伴从 LV.1、0 成长开始':p.growth?`重新启用伙伴，保留已有 ${p.growth} 点成长`:'选择喜欢的伙伴，从 LV.1 开始一起成长'}</p><form id="pet-adopt-form" data-id="${s.id}" data-cycle-id="${p.activeCycleId||''}" data-panel-id="${PanelTools.currentId(state)}">${petChoicePicker(s.pet)}<div class="dialog-actions"><button class="button" type="button" data-do="modal-close">再想想</button><button class="button primary" type="submit">确认领养</button></div></form>`);$('#modal .dialog').classList.add('student-edit-dialog');}
function petRecordsView(id='',compact=false){
 const enabled=petEnabled(),logs=[...(enabled?(state.petLogs||[]):state.logs)].reverse().filter(l=>!id||l.changes.some(c=>c.id===id)).slice(0,compact?8:300);
 return `<section class="pet-recent"><div class="section-label"><h3>${compact?'最近的成长记录':'宠物成长记录'}</h3><small>${enabled?'宠物成长独立记账':'旧版成长关联积分'}</small></div>${logs.length?logs.map(l=>`<div class="pet-history ${l.undone?'undone':''}" data-pet-log="${l.id}"><div><strong>${esc(l.reason||'课堂表现')}</strong><small>${esc(l.changes.map(c=>c.name||state.students.find(s=>s.id===c.id)?.name||'已移除学生').join('、'))}</small><small>${new Date(l.timestamp).toLocaleString('zh-CN',{hour12:false})}</small></div><b>${l.kind==='reset'?'清零成长':l.changes.some(c=>c.actualDelta!==undefined&&c.actualDelta!==l.delta)?l.changes.map(c=>`${esc(c.name||state.students.find(s=>s.id===c.id)?.name||'已移除学生')} ${Number(c.actualDelta??l.delta)>0?'+':''}${c.actualDelta??l.delta}`).join('；'):`${l.delta>0?'+':''}${l.delta}`} ${enabled?'成长':'分'}</b>${l.undone?'<span>已撤销</span>':`<button class="button" data-do="${enabled?'pet-undo':'undo'}" data-id="${l.id}">撤销整笔</button>`}</div>`).join(''):'<p class="muted">还没有成长记录，选一条课堂表现送上鼓励吧</p>'}<p class="pet-fine-print">批量操作撤销会同时还原本笔全部同学。${enabled?'撤销按原周期追溯，已毕业快照保持完整。旧版积分记录请到「积分记录」查看。':'撤销旧版积分会同步还原该笔关联成长。'}${!compact?' 此处展示最近300条，完整记录保存在备份中。':''}</p></section>`;
}
function petRankingsView(){const groups=petRankingMode==='groups',level=petRankingMode==='level';const rows=groups?PetProgress.groupRankings(state):PetProgress.studentRankings(state,{sortBy:level?'level':'medals'});return `<section class="pet-ranking-section"><h2>宠物成长荣誉榜</h2><p>${groups?'按小组成员永久徽章总数 ÷ 全组人数计算平均徽章，包括尚未领养的同学':level?'按当前宠物等级排序，未领养同学显示等待破壳':'按每位同学的永久荣誉徽章总数排序'}。同分并列，普通积分榜单独展示</p><div class="segmented"><button data-do="pet-rank-mode" data-mode="students" class="${petRankingMode==='students'?'active':''}">学生总徽章</button><button data-do="pet-rank-mode" data-mode="level" class="${level?'active':''}">学生当前等级</button><button data-do="pet-rank-mode" data-mode="groups" class="${groups?'active':''}">小组平均徽章</button></div><div class="ranking-list pet-ranking-list">${rows.map(r=>`<article ${groups?'':`data-pet-rank-student="${esc(r.id)}"`}><strong class="rank-number">${r.rank}</strong>${groups?'':`<div class="pet-rank-art">${r.adopted?petSvg(r.pet,false,r.shape):petEgg()}</div>`}<div><h3>${esc(groups?r.group:r.name)}</h3><small>${groups?`${r.count} 位成员 · 总徽章 ${r.medalTotal}`:esc(r.group)}</small>${groups?'':`<small class="pet-rank-facts">当前宠物：${r.adopted?esc(petNames[r.pet]):'未领养'} · 等级：${r.adopted?'LV.'+r.level:'等待领养'} · 总徽章：${r.medalTotal}</small>`}</div><b>${groups?Number(r.averageMedals.toFixed(3)):level?(r.adopted?'LV.'+r.level:'未领养'):r.medalTotal}<small> ${groups?'枚 / 人':level?'':'枚徽章'}</small></b></article>`).join('')||'<div class="empty">添加学生后即可查看荣誉榜</div>'}</div></section>`;}
function honorsDialog(id=''){
 const students=id?state.students.filter(s=>s.id===id):state.students,profiles=students.map(s=>({student:s,...growth(s)})),graduates=profiles.flatMap(p=>p.graduates.map(g=>({...g,owner:p.student.name}))).sort((a,b)=>b.graduatedAt-a.graduatedAt),total=profiles.reduce((n,p)=>n+p.medalTotal,0),unknown=profiles.some(p=>p.medalAvailable===null),available=unknown?null:profiles.reduce((n,p)=>n+p.medalAvailable,0);
 modal(`<div class="album-title"><span class="eyebrow">GRADUATION HONORS</span><h2>毕业荣誉世界</h2><p>${id?esc(students[0]?.name||''):esc(state.settings.className)} · 每一位毕业伙伴，都值得珍藏</p></div><div class="honor-stats"><div><strong>${total}</strong><span>总荣誉徽章</span></div><div><strong>${available===null?'待核定':available}</strong><span>可兑换徽章</span></div><div><strong>${graduates.length}</strong><span>已记录毕业次数</span></div></div>${unknown?'<p class="pet-fine-print">当前档案未提供可验证的兑换余额，显示“待核定”；不将永久荣誉总数当作可兑换余额。旧版徽章计入总荣誉，但没有可靠物种记录时不分配到相册。</p>':''}<div class="button-row">${PetExtraUI.honorActions(id)}</div><div class="honor-species-grid">${Object.entries(petNames).map(([pet,name])=>{const count=graduates.filter(g=>g.petSnapshot===pet).length;return `<article class="honor-species ${count?'has-graduates':'no-graduates'}" data-honor-pet="${pet}">${petSvg(pet,false,7)}<h3>${esc(name)}</h3><span>${count?`毕业 ${count} 次`:'尚未毕业'}</span></article>`;}).join('')}</div><h3>毕业时刻</h3><div class="graduation-snapshots">${graduates.map(g=>`<article>${petSvg(g.petSnapshot,false,7)}<div><h4>${esc(g.studentName)} · ${esc(petNames[g.petSnapshot])}</h4><p>${new Date(g.graduatedAt).toLocaleString('zh-CN',{hour12:false})} · ${esc(g.groupName)}</p><small>LV.${g.levelSnapshot} · 本轮 ${g.growthSnapshot} 成长 · 毕业门槛 ${g.ruleSnapshot.thresholds.join(' / ')}</small></div><strong>+1 🏅</strong></article>`).join('')||'<div class="empty">第一位满级伙伴毕业后，会出现在这里</div>'}</div>`);$('#modal .dialog').classList.add('honors-dialog');
}

async function handlePetSubmit(event){
 const form=event.target;if(!['pet-rules-form','pet-growth-form','pet-adopt-form','pet-switch-form'].includes(form.id))return false;event.preventDefault();if(form.dataset.saving)return true;
 if(form.dataset.panelId!==PanelTools.currentId(state)){toast('面板已切换，请重新打开操作');return true;}
 let command,message;const data=new FormData(form);
 try{
  if(form.id==='pet-rules-form'){
   if(form.dataset.mode==='legacy'){if(petEnabled())throw Error('本班已启用六段成长，请重新打开规则');const step=Number($('#pet-step').value);if(!Number.isInteger(step)||step<1||step>100)throw Error('每级成长值需为1–100整数');command={type:'pet.rules',step};message='旧版成长规则已更新，历史积分和成长值不变';}
   else{const thresholds=PetProgress.thresholds([...form.querySelectorAll('.pet-threshold')].map(input=>Number(input.value)));command={type:'pet.stage-rules',thresholds};message=petEnabled()?'六段门槛已保存，已有成长与毕业快照保留':'已启用六段成长与毕业，原积分和累计成长保留';}
  }else if(form.id==='pet-growth-form'){
   if(!pendingRewardContext||pendingRewardContext.panelId!==PanelTools.currentId(state)||!pendingRewardContext.enabled)throw Error('鼓励目标已变化，请重新选择');const amount=Number(data.get('delta')),reason=String(data.get('reason')||'').trim();if(!Number.isInteger(amount)||amount<1||amount>100)throw Error('成长值需为1–100整数');if(!reason)throw Error('请填写成长原因');command={type:'pet.growth',ids:[...pendingRewardIds],expectedCycles:pendingRewardContext.expectedCycles,delta:amount*(event.submitter?.value==='minus'?-1:1),reason};message='成长已更新，普通积分不变';
  }else if(form.id==='pet-switch-form'){const pet=data.get('pet');if(!Object.hasOwn(petNames,pet))throw Error('请选择伙伴');command={type:'pet.switch',id:form.dataset.id,pet,expectedPet:form.dataset.expectedPet,expectedCycleId:form.dataset.cycleId||null};message='伙伴已更换，积分、成长和荣誉保留';}
  else{const pet=data.get('pet');if(!Object.hasOwn(petNames,pet))throw Error('请选择一位成长伙伴');command={type:'pet.adopt',id:form.dataset.id,pet,expectedCycleId:form.dataset.cycleId||null};message='领养成功，一起开启新的成长';}
  form.dataset.saving='1';form.querySelectorAll('[type=submit]').forEach(button=>button.disabled=true);
  if(await act({...command,panelId:form.dataset.panelId},message))closeModal();else{form.dataset.saving='';form.querySelectorAll('[type=submit]').forEach(button=>button.disabled=false);}
 }catch(error){toast(error.message);form.dataset.saving='';form.querySelectorAll('[type=submit]').forEach(button=>button.disabled=false);}return true;
}
function petDrawSignature(){const draw=state.petDraw;return JSON.stringify({panelId:PanelTools.currentId(state),scope:draw?.scope,round:draw?.round,lastIds:draw?.lastIds||[],groups:draw?.groups||[]});}
function makePetDrawResult(){const draw=state.petDraw;if(!draw?.lastIds?.length)return null;return {signature:petDrawSignature(),panelId:PanelTools.currentId(state),scope:draw.scope,rows:draw.scope==='groups'?draw.groups.map(g=>({label:g.group,ids:[...g.ids],expectedCycles:g.ids.map(id=>({id,cycleId:growth(id).activeCycleId})),delta:'1',rewarded:false})):[{label:'本次抽中的同学',ids:[...draw.lastIds],expectedCycles:draw.lastIds.map(id=>({id,cycleId:growth(id).activeCycleId})),delta:'1',rewarded:false}]};}
function petDrawDialog(){
 if(!petEnabled()){modal(`<h2>宠物随机鼓励</h2><p>启用六段成长与毕业后，可以独立抽学生或抽小组，并为抽中的已领养伙伴调整成长</p><button class="button primary" data-do="pet-enable">启用分段成长与毕业</button>`);return;}
 if(petDrawResult&&petDrawResult.signature!==petDrawSignature())petDrawResult=null;
 const draw=state.petDraw||{scope:'students',mode:'cycle',round:0},adopted=state.students.filter(s=>growth(s).adopted),groupCount=new Set(adopted.map(s=>s.group)).size;
 modal(`<h2>宠物随机鼓励</h2><p>抽取已领养宠物的同学。抽小组后，每位已领养组员分别获得成长；普通积分和普通点名记录保持不变</p><div class="pet-draw-controls"><label>抽取对象<select id="pet-draw-scope"><option value="students" ${draw.scope==='students'?'selected':''}>抽学生（${adopted.length}人）</option><option value="groups" ${draw.scope==='groups'?'selected':''}>抽小组（${groupCount}组）</option></select></label><label>数量<input id="pet-draw-count" type="number" min="1" max="20" value="${petDrawCount}" step="1"></label><label>抽取方式<select id="pet-draw-mode"><option value="cycle" ${draw.mode==='cycle'?'selected':''}>本轮不重复</option><option value="repeat" ${draw.mode==='repeat'?'selected':''}>允许再次抽中</option></select></label></div><div class="button-row"><button class="button primary" data-do="pet-draw-start" ${petDrawBusy||!adopted.length?'disabled':''}>${petDrawBusy?'正在抽取…':'✦ 开始抽取'}</button><button class="button" data-do="pet-draw-reset">重新开始一轮</button><span class="muted">第 ${draw.round||0} 轮 · 不足所选数量时只抽本轮剩余对象</span></div><div id="pet-draw-results">${petDrawResult?petDrawResults():'<div class="empty">选好对象和数量，开始一次随机鼓励吧</div>'}</div>`);$('#modal .dialog').classList.add('pet-draw-dialog');
}
function petDrawResults(){if(!petDrawResult)return '';return `<h3>${petDrawResult.scope==='groups'?'本次抽中小组':'本次抽中学生'}</h3><div class="pet-draw-result-rows">${petDrawResult.rows.map((row,i)=>`<section class="pet-draw-result"><h4>${esc(row.label)}</h4><div class="pet-draw-names">${row.ids.map(id=>{const s=state.students.find(s=>s.id===id);if(!s)return '';const p=growth(s);return `<span>${petSvg(p.pet,false,p.shape)}${esc(s.name)}<small>LV.${p.level}</small></span>`;}).join('')}</div><div class="pet-draw-award"><label>每位成长<input type="number" min="-100" max="100" step="1" data-pet-draw-delta="${i}" value="${esc(row.delta)}" ${row.rewarded?'disabled':''}></label><button class="button primary" data-do="pet-draw-award" data-index="${i}" ${row.rewarded||petDrawBusy?'disabled':''}>${row.rewarded?'已记录成长':'确认本项'}</button></div></section>`).join('')}</div><p class="pet-fine-print">填写非零整数，正数增加、负数减少（−100 至 100）。每组可设置不同值</p><button class="button primary" data-do="pet-draw-award-all" ${petDrawBusy||petDrawResult.rows.every(r=>r.rewarded)?'disabled':''}>确认全部未记录项</button>`;}
async function handlePetDraw(action,el){
 if(action==='pet-draw'){if(!petDrawResult||petDrawResult.signature!==petDrawSignature())petDrawResult=makePetDrawResult();petDrawDialog();return true;}if(petDrawBusy)return true;
 if(action==='pet-draw-reset'){if(await act({type:'pet.draw.reset'},'宠物抽取已开始新一轮')){petDrawResult=null;petDrawDialog();}return true;}
 if(action==='pet-draw-start'){
  const scope=$('#pet-draw-scope').value,mode=$('#pet-draw-mode').value,count=Number($('#pet-draw-count').value),panelId=PanelTools.currentId(state);if(!Number.isInteger(count)||count<1||count>20){toast('抽取数量需为1–20的整数');return true;}
  petDrawCount=count;petDrawBusy=true;el.disabled=true;el.textContent='正在抽取…';try{if(await act({type:'pet.draw',scope,count,mode,panelId})){petDrawResult=makePetDrawResult();if($('#pet-draw-results')&&panelId===PanelTools.currentId(state))petDrawDialog();}}finally{petDrawBusy=false;if($('#pet-draw-results'))$('#pet-draw-results').innerHTML=petDrawResults();const button=$('[data-do=pet-draw-start]');if(button){button.disabled=false;button.textContent='✦ 开始抽取';}}return true;
 }
 if(action==='pet-draw-award'||action==='pet-draw-award-all'){
  if(!petDrawResult||petDrawResult.signature!==petDrawSignature()){toast('抽取名单或所属小组已变化，请重新抽取');petDrawResult=null;petDrawDialog();return true;}
  const rows=action==='pet-draw-award-all'?petDrawResult.rows.filter(row=>!row.rewarded):[petDrawResult.rows[Number(el.dataset.index)]].filter(row=>row&&!row.rewarded);if(!rows.length)return true;
  const awards=rows.map(row=>({ids:[...row.ids],expectedCycles:row.expectedCycles,delta:Number(row.delta)}));if(awards.some(a=>!Number.isInteger(a.delta)||a.delta===0||Math.abs(a.delta)>100)){toast('每项成长需为−100至100的非零整数');return true;}
  petDrawBusy=true;document.querySelectorAll('#pet-draw-results button').forEach(button=>button.disabled=true);const panelId=petDrawResult.panelId,signature=petDrawResult.signature;
  try{const ok=await act({...(awards.length===1?{type:'pet.growth',...awards[0]}:{type:'pet.growth.mixed',awards}),reason:petDrawResult.scope==='groups'?'宠物随机小组鼓励':'宠物随机学生鼓励',panelId},'已记录宠物成长，普通积分不变');if(ok&&petDrawResult?.signature===signature)rows.forEach(row=>row.rewarded=true);}finally{petDrawBusy=false;if($('#pet-draw-results'))$('#pet-draw-results').innerHTML=petDrawResults();}return true;
 }return false;
}

document.addEventListener('dblclick',e=>{if(role==='flower'&&e.target.closest('[data-do="open-panel"]')){clearTimeout(flowerClickTimer);api.window({command:native?'flower-double':'toggle',role:'panel',value:e.detail}).catch(error=>toast(error.message));}});


function petMatches(id,query){const q=String(query||'').trim().toLocaleLowerCase();if(!q)return true;if(Object.hasOwn(petNames,q))return id===q;return `${id} ${petNames[id]} ${petAliases[id]||''}`.toLocaleLowerCase().includes(q);}
function petChoicePicker(chosen){
 petChoiceFamily='all';
 return `<fieldset class="pet-choice-fieldset"><legend>选择成长伙伴 <span>${Object.keys(petNames).length}种不同宠物 · 每种7阶段</span></legend>${petFamilyControls('pet-choice-family')}<div class="pet-choice-tools"><input id="pet-choice-search" type="search" placeholder="搜索伙伴，例如：熊猫 / 机甲 / 恐龙" aria-label="搜索成长伙伴"><button type="button" class="button" data-do="pet-choice-random">随机一位</button></div><p id="pet-choice-summary" class="pet-choice-summary" aria-live="polite">已选：${esc(petNames[chosen])} · 点击图卡更换，保存后生效</p><div class="pet-choice-grid">${Object.entries(petNames).map(([id,name])=>`<label class="pet-choice ${chosen===id?'chosen':''}" data-pet="${id}"><input type="radio" name="pet" value="${id}" ${chosen===id?'checked':''} aria-label="${esc(name)}">${petSvg(id,false,4)}<strong>${esc(name)}</strong><small>${adventurePets.has(id)?'冒险伙伴':'经典伙伴'}</small></label>`).join('')}</div><p id="pet-choice-empty" class="pet-search-empty" hidden>没有找到这位伙伴，试试其他名称或清空搜索</p><small id="pet-choice-count">显示全部${Object.keys(petNames).length}种伙伴</small></fieldset>`;
}
function updatePetChoice(){
 const chosen=$('#modal input[name=pet]:checked')?.value;if(!chosen)return;
 document.querySelectorAll('.pet-choice').forEach(card=>card.classList.toggle('chosen',card.dataset.pet===chosen));
 $('#pet-choice-summary').textContent=`已选：${petNames[chosen]} · 点击图卡更换，保存后生效`;
}
function filterPetChoices(){
 const query=$('#pet-choice-search')?.value.trim()||'';let count=0;
 document.querySelectorAll('.pet-choice').forEach(card=>{card.hidden=!(petMatches(card.dataset.pet,query)&&inPetFamily(card.dataset.pet,petChoiceFamily));if(!card.hidden)count++;});
 $('#pet-choice-count').textContent=`找到 ${count} / ${Object.keys(petNames).length} 种伙伴`;
 $('#pet-choice-empty').hidden=count!==0;
 document.querySelectorAll('[data-do=pet-choice-family]').forEach(b=>{const active=b.dataset.family===petChoiceFamily;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
}
function catalogDialog(){
 catalogStage=4;catalogFamily='all';
 modal(`<div class="catalog-heading"><span class="eyebrow">MEET YOUR COMPANION · 原创宠物图鉴</span><h2>${Object.keys(petNames).length}种伙伴，等你来认识</h2><p>每种都有七段完整成长，合计${Object.keys(petNames).length*7}种造型。这里仅供浏览，选择学生后可在档案中更换</p></div>${petFamilyControls('catalog-family')}<div class="catalog-controls"><input id="pet-catalog-search" type="search" placeholder="搜索中文名或英文物种" aria-label="搜索宠物图鉴"><div class="segmented"><button type="button" data-do="catalog-stage" data-level="1">破壳宝宝</button><button type="button" data-do="catalog-stage" data-level="4">出发旅行</button><button type="button" data-do="catalog-stage" data-level="7">星光守护</button></div></div><p id="catalog-count" class="catalog-count" aria-live="polite"></p><div id="catalog-grid" class="catalog-grid"></div><p class="catalog-foot">完整七阶段可在每位学生的「进化图鉴」中逐一查看 · 预览不会改变课堂数据</p>`);
 $('#modal .dialog').classList.add('catalog-dialog');renderCatalog();
}
function renderCatalog(){
 if(!$('#catalog-grid'))return;const query=$('#pet-catalog-search')?.value.trim()||'';
 const entries=Object.entries(petNames).filter(([id])=>petMatches(id,query)&&inPetFamily(id,catalogFamily));
 $('#catalog-count').textContent=`${entries.length} / ${Object.keys(petNames).length}种伙伴 · 正在预览 LV.${catalogStage} ${hiddenPetForm(catalogStage)?'神秘形态（老师已隐藏）':PetArt.stages[catalogStage-1]}`;
 $('#catalog-grid').innerHTML=entries.length?entries.map(([id,name],index)=>`<article class="catalog-card" data-catalog-pet="${id}"><span class="catalog-number">${String(Object.keys(petNames).indexOf(id)+1).padStart(2,'0')}</span>${petPreviewArt(id,catalogStage)}<h3>${esc(name)}</h3><p>7段成长 · 独立物种</p></article>`).join(''):'<div class="pet-search-empty">没有找到这位伙伴，试试“海豹”“熊猫”或清空搜索</div>';
 document.querySelectorAll('[data-do=catalog-family]').forEach(b=>{const active=b.dataset.family===catalogFamily;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 document.querySelectorAll('[data-do=catalog-stage]').forEach(b=>{const active=Number(b.dataset.level)===catalogStage;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
}
